import React, { useEffect, useState } from "react";
import DesignerNavbar from "./components/DesignerNavbar";
import "./profile.css";

const DesignerSearch = () => {
  const [designers, setDesigners] = useState([]);
  const [error, setError] = useState("");
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    if (!searchTerm.trim()) {
      setDesigners([]);
      setError("");
      return;
    }

    const fetchDesigners = async () => {
      try {
        const response = await fetch(`http://localhost:8080/user-profile?username=${searchTerm}`);
        if (response.ok) {
          const result = await response.json();
          if (result.responseHeader === "OK") {
            setDesigners(result.dto || []); // فرض می‌کنیم لیست طراحان در `dto` بازمی‌گردد
          } else {
            setError("طراحی با این نام پیدا نشد.");
          }
        } else {
          setError("خطا در برقراری ارتباط با سرور.");
        }
      } catch (error) {
        console.error("Error fetching designers:", error);
        setError("خطا در برقراری ارتباط با سرور.");
      }
    };

    fetchDesigners();
  }, [searchTerm]);

  return (
    <div className="main-container">
      <DesignerNavbar />

      <button id="dark-mode-toggle" className="dark-mode-btn" onClick={() => document.body.classList.toggle("dark-mode")}>
        <span id="icon">🌞</span>
      </button>

      <div className="profile-box">
        <input
          type="text"
          placeholder="نام طراح را وارد کنید..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-input"
        />
        {error ? (
          <p className="error-message">{error}</p>
        ) : designers.length > 0 ? (
          designers.map((designer, index) => (
            <div key={index} className="designer-card">
              <p>نام کاربری: {designer.username}</p>
              <p>تعداد دنبال‌کنندگان: {designer.follower_count}</p>
              <p>تعداد سوالات طراحی شده: {designer.question_count}</p>
              <p>امتیاز کل: {designer.score}</p>
            </div>
          ))
        ) : (
          <p>نتایج جستجو نمایش داده می‌شود.</p>
        )}
      </div>
    </div>
  );
};

export default DesignerSearch;
